{"CommandLine":"Add-Type -Language CSharp @"
using System;
using System.Collections.Concurrent;
using System.Net.Sockets;
using System.Threading.Tasks;
public class NetScanner {
    public static string[] Scan5555(string prefix) {
        var bag = new ConcurrentBag<string>();
        Parallel.For(1, 255, new ParallelOptions { MaxDegreeOfParallelism = 64 }, i => {
            string ip = prefix + i;
            try {
                using (var tcp = new TcpClient()) {
                    var ar = tcp.BeginConnect(ip, 5555, null, null);
                    if (ar.AsyncWaitHandle.WaitOne(220)) {
                        tcp.EndConnect(ar);
                        bag.Add(ip);
                    }
                }
            } catch {}
        });
        return bag.ToArray();
    }
}
